// Extract task data from the webhook payload
const taskData = $input.item.json.task_data;

if (!taskData) {
  throw new Error('Missing task_data in webhook payload');
}

// Extract content from the task data
let content = taskData.content || '';
if (!content && taskData.original_message) {
  content = taskData.original_message;
}

// Generate tags if not provided
let tags = taskData.tags || [];
if (tags.length === 0 && taskData.category) {
  tags.push(taskData.category);
}

// Generate a unique ID for the idea
const timestamp = Math.floor(Date.now() / 1000);
const id = `idea_${timestamp}`;

// Create the idea object
const idea = {
  id,
  content,
  tags,
  timestamp: new Date().toISOString(),
  source: 'telegram',
  user_id: taskData.user_id || '',
  username: taskData.username || '',
  original_message: taskData.original_message || ''
};

// Add any additional fields from the task data
for (const [key, value] of Object.entries(taskData)) {
  if (!(key in idea) && !['task_type', 'task_data'].includes(key)) {
    idea[key] = value;
  }
}

return { json: idea };

// Combine all context into a single object
const similarIdeas = $node["Query Similar Ideas"].json.results || [];
const upcomingEvents = $node["Query Calendar Events"].json.items || [];

return {
  json: {
    ...$input.item.json,
    context: {
      similar_ideas: similarIdeas,
      upcoming_events: upcomingEvents
    }
  }
};

// Extract the AI analysis
const aiResponse = $input.item.json.response;
let aiAnalysis;

try {
  // If the response is already parsed JSON
  if (typeof aiResponse === 'object') {
    aiAnalysis = aiResponse;
  } else {
    // If it's a string that needs parsing
    aiAnalysis = JSON.parse(aiResponse);
  }
} catch (error) {
  // Fallback if parsing fails
  aiAnalysis = {
    analysis: "Unable to analyze the idea in context.",
    is_duplicate: false,
    related_ideas: [],
    relevant_events: [],
    suggested_tags: [],
    next_steps: [],
    enhanced_content: $input.item.json.content
  };
}

// Enhance the idea with AI analysis
const enhancedIdea = {
  ...$input.item.json,
  tags: [...new Set([...$input.item.json.tags, ...aiAnalysis.suggested_tags])], // Combine tags, remove duplicates
  is_duplicate: aiAnalysis.is_duplicate,
  related_ideas: aiAnalysis.related_ideas,
  relevant_events: aiAnalysis.relevant_events,
  enhanced_content: aiAnalysis.enhanced_content,
  ai_analysis: aiAnalysis
};

return { json: enhancedIdea };

